                      '        value_start = cfg.key_packed_size\n'
                      '        value_end = value_start + d // 2\n'
                      '        assert torch.equal(actual_slots[..., :value_start], '
                      'expected_key_bytes)\n'
                      '        assert torch.equal(actual_slots[..., value_end:386], '
                      'scale_bytes)\n'
                      '        assert torch.equal(actual_slots[..., 386:388], '
